import React, { useEffect, useState } from 'react';
import { Check, ChevronDown, MapPin, X } from 'lucide-react';
import { CenterModal } from '../ui/Modal';
import { useDraggableScroll } from '../../hooks/useDraggableScroll';
import { CampusBuilding } from '../../types';

interface LocationSelectorProps {
  selectedLocations: string[];
  setSelectedLocations: (locs: string[]) => void;
  buildings: CampusBuilding[];
  className?: string;
  allLabel?: string;
}

export function LocationSelector({
  selectedLocations,
  setSelectedLocations,
  buildings,
  className,
  allLabel = '全校',
}: LocationSelectorProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [tempLocations, setTempLocations] = useState<string[]>([]);
  const dragProps = useDraggableScroll<HTMLDivElement>();

  useEffect(() => {
    if (isOpen) {
      setTempLocations([...selectedLocations]);
    }
  }, [isOpen, selectedLocations]);

  const toggleLocation = (loc: string) => {
    if (loc === allLabel) {
      setTempLocations(tempLocations.includes(allLabel) ? [] : [allLabel]);
      return;
    }
    let newLocs = tempLocations.filter(item => item !== allLabel);
    if (newLocs.includes(loc)) {
      newLocs = newLocs.filter(item => item !== loc);
    } else {
      newLocs.push(loc);
    }
    setTempLocations(newLocs);
  };

  const handleSave = () => {
    setSelectedLocations([...tempLocations]);
    setIsOpen(false);
  };

  const isSelected = selectedLocations && selectedLocations.length > 0;
  const locationSummary = !isSelected || selectedLocations.includes(allLabel)
    ? allLabel
    : selectedLocations.length === 1
      ? selectedLocations[0]
      : `${selectedLocations.length}处地点`;

  return (
    <>
      <button
        type="button"
        onClick={() => setIsOpen(true)}
        className={className || `w-full h-10 px-3 flex items-center justify-between gap-1.5 rounded-xl transition-all shadow-sm ${isSelected ? 'bg-pink-50 text-pink-700 border border-pink-200' : 'bg-white/60 text-text-primary border border-border-default'} hover:bg-white cursor-pointer`}
        title="选择生效地点"
      >
        <div className="flex items-center gap-1.5 min-w-0">
          <MapPin className="w-4 h-4 text-pink-500 shrink-0" />
          <span className="text-xs font-bold truncate">{locationSummary}</span>
        </div>
        <ChevronDown className="w-3.5 h-3.5 opacity-50 shrink-0" />
      </button>

      <CenterModal
        isOpen={isOpen}
        onClose={() => setIsOpen(false)}
        className="glass w-[280px] max-h-[60vh] rounded-[20px] border border-white/50 shadow-xl"
      >
        <div
          className="shrink-0 flex items-center justify-between p-4 border-b border-border-default"
          onPointerDown={e => e.stopPropagation()}
        >
          <h3 className="text-base font-bold text-text-primary flex items-center gap-2">
            <MapPin className="w-4 h-4 text-pink-500" />
            选择所在地
          </h3>
          <button
            onClick={() => setIsOpen(false)}
            className="p-1.5 bg-white/50 rounded-full text-text-secondary hover:bg-white/80 transition-colors shadow-sm border border-border-default"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        <div
          className="flex-1 overflow-y-auto overflow-x-hidden p-3 space-y-2 hide-scrollbar select-none cursor-grab active:cursor-grabbing touch-none"
          {...dragProps}
          ref={dragProps.ref}
          onPointerDown={e => {
            e.stopPropagation();
            if (dragProps.onPointerDown) dragProps.onPointerDown(e);
          }}
        >
          <div
            onClick={() => toggleLocation(allLabel)}
            className={`flex items-center justify-between p-3 rounded-2xl cursor-pointer transition-colors border shadow-sm ${tempLocations.includes(allLabel) ? 'bg-pink-50/80 border-pink-200' : 'bg-white/60 border-border-default hover:bg-white/80'}`}
          >
            <div className="flex items-center gap-3">
              <div className={`w-4 h-4 rounded flex items-center justify-center transition-colors shadow-sm ${tempLocations.includes(allLabel) ? 'bg-pink-500 text-white border-pink-500' : 'bg-surface-solid border border-border-default'}`}>
                {tempLocations.includes(allLabel) && <Check className="w-3 h-3" />}
              </div>
              <span className={`text-sm font-bold ${tempLocations.includes(allLabel) ? 'text-pink-700' : 'text-text-primary'}`}>{allLabel}</span>
            </div>
          </div>

          {buildings.map(building => (
            <div
              key={building.id}
              onClick={() => toggleLocation(building.name)}
              className={`flex items-center justify-between p-3 rounded-2xl cursor-pointer transition-colors border shadow-sm ${tempLocations.includes(building.name) ? 'bg-pink-50/80 border-pink-200' : 'bg-white/60 border-border-default hover:bg-white/80'}`}
            >
              <div className="flex items-center gap-3">
                <div className={`w-4 h-4 rounded flex items-center justify-center transition-colors shadow-sm ${tempLocations.includes(building.name) ? 'bg-pink-500 text-white border-pink-500' : 'bg-surface-solid border border-border-default'}`}>
                  {tempLocations.includes(building.name) && <Check className="w-3 h-3" />}
                </div>
                <span className={`text-sm font-medium ${tempLocations.includes(building.name) ? 'text-pink-700' : 'text-text-primary'}`}>{building.name}</span>
              </div>
            </div>
          ))}
        </div>

        <div
          className="shrink-0 p-3 border-t border-border-default flex gap-2"
          onPointerDown={e => e.stopPropagation()}
        >
          <button
            onClick={() => setIsOpen(false)}
            className="flex-1 py-2.5 text-sm glass text-text-secondary font-bold rounded-xl hover:bg-white/80 transition-colors shadow-sm border border-border-default"
          >
            取消
          </button>
          <button
            onClick={handleSave}
            className="flex-1 py-2.5 text-sm bg-gradient-to-r from-pink-400 to-rose-400 text-white font-bold rounded-xl hover:from-pink-500 hover:to-rose-500 transition-colors shadow-md shadow-pink-200"
          >
            保存
          </button>
        </div>
      </CenterModal>
    </>
  );
}
