import React, { useState, useEffect } from 'react';
import { createPortal } from 'react-dom';
import { motion, AnimatePresence } from 'framer-motion';
import { X, ChevronLeft } from 'lucide-react';

export function PhonePortal({ children }: { children: React.ReactNode }) {
  const [frame, setFrame] = useState<Element | null>(null);
  
  useEffect(() => {
    setFrame(document.querySelector('.phone-screen') || document.querySelector('.phone-frame') || document.body);
  }, []);

  if (!frame) return null;
  return createPortal(children, frame);
}

interface FullScreenModalProps {
  children: React.ReactNode;
  isOpen: boolean;
  onClose?: () => void;
  className?: string;
}

export function FullScreenModal({ children, isOpen, onClose, className = '' }: FullScreenModalProps) {
  return (
    <PhonePortal>
      <AnimatePresence>
        {isOpen && (
          <motion.div 
            initial={{ y: '100%', opacity: 0 }}
            animate={{ y: 0, opacity: 1 }}
            exit={{ y: '100%', opacity: 0 }}
            transition={{ type: 'spring', damping: 25, stiffness: 300 }}
            className={`absolute inset-x-0 top-12 bottom-[var(--phone-nav-height,0px)] flex flex-col min-h-0 overflow-hidden glass ${className.includes('z-') ? '' : 'z-[85]'} ${className}`}
          >
            {onClose && (
              <div className="px-4 flex items-center justify-end absolute top-4 right-4 z-10 w-full pointer-events-none">
                <button 
                  onClick={onClose} 
                  className="p-2 glass rounded-full hover:bg-black/5 transition-colors shadow-sm pointer-events-auto text-text-primary"
                >
                  <ChevronLeft className="w-5 h-5" />
                </button>
              </div>
            )}
            {children}
          </motion.div>
        )}
      </AnimatePresence>
    </PhonePortal>
  );
}

interface BottomSheetModalProps {
  children: React.ReactNode;
  isOpen: boolean;
  onClose: () => void;
  className?: string;
  snapPoints?: string[]; // E.g., ['50%', '85%']
}

export function BottomSheetModal({ children, isOpen, onClose, className = '' }: BottomSheetModalProps) {
  const zClass = className.match(/(?:^|\s)(z-\[[^\]]+\]|z-\d+)(?:\s|$)/)?.[1] || 'z-[90]';
  const panelClass = className
    .replace(/(?:^|\s)(z-\[[^\]]+\]|z-\d+)(?=\s|$)/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();

  return (
    <PhonePortal>
      <AnimatePresence>
        {isOpen && (
          <div className={`absolute inset-x-0 top-12 bottom-0 ${zClass} flex items-end justify-center pointer-events-none`}>
            <motion.div 
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="absolute inset-0 bg-black/20 backdrop-blur-sm pointer-events-auto"
              onClick={onClose}
            />
            <motion.div 
              initial={{ y: '100%', opacity: 0 }}
              animate={{ y: 0, opacity: 1 }}
              exit={{ y: '100%', opacity: 0 }}
              transition={{ type: 'spring', damping: 25, stiffness: 300 }}
              data-no-drag-scroll
              className={`w-full bg-surface-solid rounded-t-[32px] shadow-2xl relative flex flex-col pointer-events-auto overflow-hidden border-t border-border-default ${
                panelClass.includes('h-') ? '' : 'h-[85%]'
              } ${panelClass}`}
              onClick={e => e.stopPropagation()}
              onPointerDown={e => e.stopPropagation()}
            >
              <div className="absolute top-3 left-1/2 -translate-x-1/2 w-12 h-1.5 bg-border-default rounded-full" />
              
              {children}
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </PhonePortal>
  );
}

interface CenterModalProps {
  children: React.ReactNode;
  isOpen: boolean;
  onClose: () => void;
  className?: string;
}

export function CenterModal({ children, isOpen, onClose, className = '' }: CenterModalProps) {
  return (
    <PhonePortal>
      <AnimatePresence>
        {isOpen && (
          <div className="absolute inset-x-0 top-12 bottom-0 z-[90] flex items-center justify-center pointer-events-none p-4">
            <motion.div 
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              exit={{ opacity: 0 }}
              className="absolute inset-0 bg-black/40 backdrop-blur-sm pointer-events-auto"
              onClick={onClose}
            />
            <motion.div 
              initial={{ scale: 0.95, opacity: 0, y: 10 }}
              animate={{ scale: 1, opacity: 1, y: 0 }}
              exit={{ scale: 0.95, opacity: 0, y: 10 }}
              transition={{ type: 'spring', damping: 25, stiffness: 300 }}
              data-no-drag-scroll
              className={`relative flex flex-col pointer-events-auto overflow-hidden border border-border-default bg-surface-solid rounded-[24px] shadow-2xl ${className || 'w-full max-w-sm'}`}
              onPointerDown={e => e.stopPropagation()}
              onPointerMove={e => e.stopPropagation()}
              onWheel={e => e.stopPropagation()}
              onTouchMove={e => e.stopPropagation()}
            >
              {children}
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </PhonePortal>
  );
}
