import { BookOpen, Building2, ChevronDown, Search, TextCursorInput, Trash2, Users } from 'lucide-react';
import { useMemo, useState } from 'react';
import { SchoolRule } from '../../types';
import { groupRulesByCategory } from '../../utils/workshopPack';
import { Card } from '../ui/Card';
import { ConfirmDialog } from '../ui/ConfirmDialog';
import { CenterModal } from '../ui/Modal';

export type ManageTab = 'rules' | 'characters' | 'buildings';
export type ArchiveRow = {
  name: string;
  enabled?: boolean;
  displayName?: string;
  extra?: string;
  content?: string;
};

export function WorkshopManagePanel({
  tab,
  onTabChange,
  rules,
  characters,
  buildings,
  loading,
  onArchiveToggle,
  onSendRule,
  onDelete,
}: {
  tab: ManageTab;
  onTabChange: (tab: ManageTab) => void;
  rules: SchoolRule[];
  characters: ArchiveRow[];
  buildings: ArchiveRow[];
  loading: boolean;
  onArchiveToggle: (kind: 'characters', name: string, enabled: boolean) => void;
  onSendRule: (rule: SchoolRule) => void;
  onDelete: (kind: ManageTab, id: string) => void;
}) {
  const [openCategories, setOpenCategories] = useState<Record<string, boolean>>({});
  const [detail, setDetail] = useState<{ title: string; extra?: string; content: string } | null>(null);
  const [pending, setPending] = useState<{ kind: ManageTab; id: string; label: string } | null>(null);
  const groupedRules = useMemo(() => groupRulesByCategory(rules), [rules]);

  return (
    <Card className="p-0 overflow-hidden" glass={false}>
      <div className="p-4 border-b border-border-default">
        <h3 className="font-bold text-text-primary">工坊管理</h3>
        <p className="text-[11px] text-text-secondary mt-1">角色勾选同步世界书开关，校规可写入输入栏</p>
      </div>
      <div className="grid grid-cols-3 gap-1 p-2 bg-gray-50">
        {([
          { id: 'rules', label: '校规', icon: BookOpen },
          { id: 'characters', label: '角色', icon: Users },
          { id: 'buildings', label: '建筑', icon: Building2 },
        ] as const).map(item => (
          <button
            key={item.id}
            type="button"
            onClick={() => onTabChange(item.id)}
            className={`py-2 rounded-xl text-[11px] font-bold flex flex-col items-center gap-0.5 ${
              tab === item.id ? 'bg-white text-pink-500 shadow-sm' : 'text-text-secondary'
            }`}
          >
            <item.icon className="w-3.5 h-3.5" />
            {item.label}
          </button>
        ))}
      </div>
      <div className="p-3 space-y-2 max-h-[46vh] overflow-y-auto hide-scrollbar">
        {tab === 'rules' &&
          groupedRules.map(group => {
            const open = Boolean(openCategories[group.category]);
            return (
              <div key={group.category} className="rounded-2xl border border-border-default bg-white overflow-hidden">
                <button
                  type="button"
                  onClick={() => setOpenCategories(prev => ({ ...prev, [group.category]: !prev[group.category] }))}
                  className="w-full px-3 py-2.5 flex items-center justify-between"
                >
                  <span className="text-sm font-bold text-text-primary">{group.category}</span>
                  <span className="flex items-center gap-1 text-[11px] text-text-secondary">
                    {group.rules.length} 条
                    <ChevronDown className={`w-4 h-4 transition-transform ${open ? 'rotate-180' : ''}`} />
                  </span>
                </button>
                {open && (
                  <div className="px-2 pb-2 space-y-1.5 border-t border-border-default/50">
                    {group.rules.map(rule => (
                      <div key={rule.id} className="pt-2 flex items-center gap-2">
                        <div className="min-w-0 flex-1">
                          <div className="text-sm font-bold text-text-primary truncate">{rule.title}</div>
                          <div className="text-[11px] text-text-secondary truncate">{rule.locationNames?.length ? rule.locationNames.join('、') : '全校'}</div>
                        </div>
                        <div className="flex items-center gap-1 shrink-0">
                          <button type="button" onClick={() => onSendRule(rule)} className="w-8 h-8 rounded-full bg-pink-50 text-pink-500 flex items-center justify-center" title="导入输入栏">
                            <TextCursorInput className="w-4 h-4" />
                          </button>
                          <button type="button" onClick={() => setDetail({
                            title: rule.title,
                            extra: `${rule.category || '其他'} · ${rule.locationNames?.length ? rule.locationNames.join('、') : '全校'}`,
                            content: rule.content,
                          })} className="w-8 h-8 rounded-full bg-gray-50 text-text-secondary flex items-center justify-center" title="查看详情">
                            <Search className="w-4 h-4" />
                          </button>
                          <button type="button" onClick={() => setPending({ kind: 'rules', id: rule.id, label: rule.title })} className="w-8 h-8 rounded-full bg-rose-50 text-rose-500 flex items-center justify-center" title="删除">
                            <Trash2 className="w-4 h-4" />
                          </button>
                        </div>
                      </div>
                    ))}
                  </div>
                )}
              </div>
            );
          })}
        {tab === 'rules' && !rules.length && <p className="text-xs text-text-secondary text-center py-8">暂无 MVU 校规</p>}

        {tab === 'characters' &&
          characters.map(item => (
            <div key={item.name} className="flex items-center gap-2 rounded-2xl border border-border-default bg-white p-3">
              <input type="checkbox" checked={item.enabled !== false} onChange={event => onArchiveToggle('characters', item.name, event.target.checked)} className="accent-pink-500" />
              <div className="min-w-0 flex-1">
                <div className="text-sm font-bold text-text-primary truncate">{item.displayName || item.name}</div>
                <div className="text-[11px] text-text-secondary truncate">{item.extra}</div>
              </div>
              <button type="button" onClick={() => setDetail({ title: item.displayName || item.name, extra: item.extra, content: item.content || '' })} className="w-8 h-8 rounded-full bg-gray-50 text-text-secondary flex items-center justify-center shrink-0" title="查看详情">
                <Search className="w-4 h-4" />
              </button>
              <button type="button" onClick={() => setPending({ kind: 'characters', id: item.name, label: item.displayName || item.name })} className="w-8 h-8 rounded-full bg-rose-50 text-rose-500 flex items-center justify-center shrink-0" title="删除">
                <Trash2 className="w-4 h-4" />
              </button>
            </div>
          ))}
        {tab === 'characters' && !loading && !characters.length && <p className="text-xs text-text-secondary text-center py-8">世界书中还没有角色档案</p>}

        {tab === 'buildings' &&
          buildings.map(item => (
            <div key={item.name} className="flex items-center gap-2 rounded-2xl border border-border-default bg-white p-3">
              <div className="min-w-0 flex-1">
                <div className="text-sm font-bold text-text-primary truncate">{item.displayName || item.name}</div>
                <div className="text-[11px] text-text-secondary truncate">{item.extra}</div>
              </div>
              <button type="button" onClick={() => setDetail({ title: item.displayName || item.name, extra: item.extra, content: item.content || '' })} className="w-8 h-8 rounded-full bg-gray-50 text-text-secondary flex items-center justify-center shrink-0" title="查看详情">
                <Search className="w-4 h-4" />
              </button>
              <button type="button" onClick={() => setPending({ kind: 'buildings', id: item.name, label: item.displayName || item.name })} className="w-8 h-8 rounded-full bg-rose-50 text-rose-500 flex items-center justify-center shrink-0" title="删除">
                <Trash2 className="w-4 h-4" />
              </button>
            </div>
          ))}
        {tab === 'buildings' && !buildings.length && <p className="text-xs text-text-secondary text-center py-8">暂无 MVU 建筑</p>}
        {loading && tab === 'characters' && <p className="text-xs text-text-secondary text-center py-8">正在读取世界书…</p>}
      </div>

      <CenterModal isOpen={Boolean(detail)} onClose={() => setDetail(null)} className="w-[calc(100%-2rem)] max-w-[320px] max-h-[75vh] p-0">
        {detail && (
          <>
            <div className="p-4 border-b border-border-default">
              <h3 className="font-bold text-text-primary">{detail.title}</h3>
              {detail.extra ? <p className="text-[11px] text-text-secondary mt-1">{detail.extra}</p> : null}
            </div>
            <pre className="p-4 text-xs leading-relaxed text-text-secondary whitespace-pre-wrap break-words overflow-y-auto max-h-[48vh] hide-scrollbar">
              {detail.content || '暂无内容'}
            </pre>
          </>
        )}
      </CenterModal>
      <ConfirmDialog
        open={Boolean(pending)}
        title="确认删除"
        message={pending ? `确定删除「${pending.label}」？此操作不可撤销。` : ''}
        onClose={() => setPending(null)}
        onConfirm={() => {
          if (!pending) return;
          onDelete(pending.kind, pending.id);
          setPending(null);
        }}
      />
    </Card>
  );
}
