import { loadCustomCampusTypes } from './campusCatalog';
import { resolveSakuraWorldbookName } from './playerArchive';

export interface ClassmateArchive {
  uid?: number;
  name: string;
  campusType: string;
  content: string;
  custom?: boolean;
  displayName: string;
  age: string;
  gender: string;
  identity: string;
  relation: string;
}

const ROLE_ENTRY_PATTERN = /^(.+)_(.+)_角色档案$/;

export function getCampusTypeLabel(typeId: string): string {
  return loadCustomCampusTypes().find(item => item.id === typeId)?.name || typeId;
}

export function parseRoleArchiveName(name: string): { character: string; campusType: string } | null {
  const match = name.match(ROLE_ENTRY_PATTERN);
  if (!match) return null;
  return { character: match[1], campusType: match[2] };
}

function escapeRegExp(label: string): string {
  return label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function parseContentLines(content: string): { indent: number; text: string; trimmed: string }[] {
  return content.split(/\r?\n/).map(text => {
    const indent = text.match(/^[ \t]*/)?.[0].length ?? 0;
    return { indent, text, trimmed: text.trim() };
  });
}

function headingMatch(trimmed: string, label: string): { value: string } | null {
  const match = trimmed.match(new RegExp(`^${escapeRegExp(label)}[：:]\\s*(.*)$`));
  if (!match) return null;
  return { value: match[1].trim() };
}

function fieldValue(content: string, label: string): string {
  const matches = parseContentLines(content)
    .map(line => {
      const match = headingMatch(line.trimmed, label);
      return match ? { indent: line.indent, value: match.value } : null;
    })
    .filter((item): item is { indent: number; value: string } => Boolean(item));
  const valued = matches.filter(item => item.value);
  if (!valued.length) return '';
  return valued.sort((a, b) => b.indent - a.indent)[0].value;
}

function firstIdentity(content: string): string {
  const block = content.match(/身份[：:]?\s*\n((?:\s*-\s*.+\n?)+)/);
  if (block) {
    const first = block[1]
      .split('\n')
      .map(line => line.replace(/^\s*-\s*/, '').trim())
      .find(Boolean);
    if (first) return first;
  }
  return fieldValue(content, '身份');
}

export interface ManifestationStage {
  id: string;
  name: string;
  items: string[];
}

export interface NamedTraitGroup {
  id: string;
  name: string;
  manifestations: string[];
  stages: ManifestationStage[];
}

export interface RoleArchiveForm {
  name: string;
  gender: string;
  age: string;
  identities: string[];
  relation: string;
  height: string;
  temperament: string;
  hairColor: string;
  hairStyle: string;
  hairAccessory: string;
  eyes: string;
  faceShape: string;
  chest: string;
  waist: string;
  legs: string;
  hips: string;
  top: string;
  bottom: string;
  underwear: string;
  accessory: string;
  personalityTraits: NamedTraitGroup[];
  constitutions: NamedTraitGroup[];
  pussy: string;
  anus: string;
  fetishes: string[];
  voice: string;
  catchphrases: string[];
  arousedBehaviors: string[];
  habits: string[];
}

function createId(prefix: string): string {
  return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 6)}`;
}

export function createManifestationStage(name = '', items: string[] = ['']): ManifestationStage {
  return {
    id: createId('stage'),
    name,
    items: items.length ? items : [''],
  };
}

export function createTraitGroup(
  name = '',
  manifestations: string[] = [''],
  stages: ManifestationStage[] = [],
): NamedTraitGroup {
  return {
    id: createId('trait'),
    name,
    manifestations: manifestations.length || stages.length ? manifestations : [''],
    stages,
  };
}

function collectField(content: string, label: string): string {
  return fieldValue(content, label);
}

function collectList(content: string, label: string): string[] {
  const lines = parseContentLines(content);
  const headingIndex = lines.findIndex(line => headingMatch(line.trimmed, label));
  if (headingIndex < 0) {
    const single = fieldValue(content, label);
    return single ? [single] : [];
  }

  const heading = lines[headingIndex];
  const items: string[] = [];
  for (let index = headingIndex + 1; index < lines.length; index += 1) {
    const line = lines[index];
    if (!line.trimmed) continue;
    if (line.indent <= heading.indent) break;
    const bullet = line.trimmed.match(/^-\s*(.*)$/);
    if (bullet) {
      const value = bullet[1].trim();
      if (value) items.push(value);
      continue;
    }
    if (headingMatch(line.trimmed, '表现形式') || /[：:]\s*$/.test(line.trimmed)) {
      continue;
    }
    break;
  }
  if (items.length) return items;
  const single = headingMatch(heading.trimmed, label)?.value;
  return single ? [single] : [];
}

function sliceSection(content: string, startLabel: string, endLabel?: string): string {
  const lines = parseContentLines(content);
  const startIndex = lines.findIndex(line => headingMatch(line.trimmed, startLabel));
  if (startIndex < 0) return '';
  const startIndent = lines[startIndex].indent;
  let endIndex = lines.length;
  if (endLabel) {
    const found = lines.findIndex(
      (line, index) => index > startIndex && line.indent <= startIndent && headingMatch(line.trimmed, endLabel),
    );
    if (found >= 0) endIndex = found;
  }
  return lines.slice(startIndex, endIndex).map(line => line.text).join('\n');
}

function parseManifestations(block: string): { items: string[]; stages: ManifestationStage[] } {
  const reserved = new Set(['表现形式', '私密部位', '性癖取向', '小穴', '后庭', '敏感度', '核心特质', '核心体质']);
  const lines = parseContentLines(block);
  const manifestationIndex = lines.findIndex(line => headingMatch(line.trimmed, '表现形式'));
  const headingIndex = manifestationIndex >= 0 ? manifestationIndex : 0;
  const heading = lines[headingIndex] || lines[0];
  const items: string[] = [];
  const stages: ManifestationStage[] = [];
  if (!heading) return { items, stages };

  for (let index = headingIndex + 1; index < lines.length; index += 1) {
    const line = lines[index];
    if (!line.trimmed) continue;
    if (line.indent < heading.indent) break;
    if (headingMatch(line.trimmed, '表现形式')) continue;
    const bullet = line.trimmed.match(/^-\s*(.*)$/);
    if (bullet) {
      const value = bullet[1].trim();
      if (value) items.push(value);
      continue;
    }
    if (line.indent === heading.indent) break;
    const nested = line.trimmed.match(/^([^：:]+)[：:]\s*(.*)$/);
    if (!nested || line.trimmed.startsWith('-')) continue;
    const stageName = nested[1].trim();
    if (!stageName || reserved.has(stageName)) continue;
    const stageItems: string[] = [];
    if (nested[2].trim()) stageItems.push(nested[2].trim());
    let cursor = index + 1;
    for (; cursor < lines.length; cursor += 1) {
      const child = lines[cursor];
      if (!child.trimmed) continue;
      if (child.indent <= line.indent) break;
      const childBullet = child.trimmed.match(/^-\s*(.*)$/);
      if (childBullet) {
        const value = childBullet[1].trim();
        if (value) stageItems.push(value);
      }
    }
    stages.push(createManifestationStage(stageName, stageItems.length ? stageItems : ['']));
    index = cursor - 1;
  }

  if (stages.length) {
    return { items: [], stages };
  }
  return { items, stages };
}

function parseTraitGroups(section: string, kind: '核心特质' | '核心体质'): NamedTraitGroup[] {
  const skipped = new Set(['表现形式', '私密部位', '性癖取向', '小穴', '后庭', '敏感度', kind]);
  const lines = parseContentLines(section);
  const kindIndex = lines.findIndex(line => headingMatch(line.trimmed, kind));
  const startIndex = kindIndex >= 0 ? kindIndex : 0;
  const startIndent = kindIndex >= 0 ? lines[kindIndex].indent : 0;
  const groups: NamedTraitGroup[] = [];
  let traitIndent: number | null = null;

  for (let index = startIndex + (kindIndex >= 0 ? 1 : 0); index < lines.length; index += 1) {
    const line = lines[index];
    if (!line.trimmed) continue;
    if (kindIndex >= 0 && line.indent <= startIndent) break;
    const heading = line.trimmed.match(/^([^：:]+)[：:]\s*(.*)$/);
    if (!heading || line.trimmed.startsWith('-')) continue;
    const name = heading[1].trim();
    if (!name || skipped.has(name)) continue;
    if (traitIndent === null) traitIndent = line.indent;
    if (line.indent !== traitIndent) continue;
    const blockEnd = lines.findIndex(
      (next, nextIndex) =>
        nextIndex > index &&
        next.trimmed &&
        next.indent <= line.indent &&
        !next.trimmed.startsWith('-'),
    );
    const block = lines
      .slice(index, blockEnd >= 0 ? blockEnd : lines.length)
      .map(item => item.text)
      .join('\n');
    const parsed = parseManifestations(block);
    groups.push(createTraitGroup(name, parsed.items, parsed.stages));
    if (blockEnd < 0) break;
    index = blockEnd - 1;
  }

  if (groups.length) return groups;
  const parsed = parseManifestations(section);
  if (parsed.items.length || parsed.stages.length) {
    return [createTraitGroup('', parsed.items, parsed.stages)];
  }
  return [createTraitGroup()];
}

