export function parseRoleArchiveForm(content: string, fallbackName = ''): RoleArchiveForm {
  const identities = collectList(content, '身份');
  const personalitySection = sliceSection(content, '性格特点', 'NSFW_核心档案');
  const nsfwSection = sliceSection(content, 'NSFW_核心档案', '语言特征');
  const speechSection = sliceSection(content, '语言特征', '日常习惯');
  const habitSection = sliceSection(content, '日常习惯');
  const aroused =
    collectList(speechSection || content, '情动时表现').length > 0
      ? collectList(speechSection || content, '情动时表现')
      : collectList(speechSection || content, '情动时');

  return {
    name: collectField(content, '姓名') || fallbackName,
    gender: collectField(content, '性别') || '女',
    age: collectField(content, '年龄'),
    identities: identities.length ? identities : [''],
    relation: collectField(content, '与{{user}}关系') || collectField(content, '与user关系'),
    height: collectField(content, '身高'),
    temperament: collectField(content, '气质') || collectField(content, '皮肤'),
    hairColor: collectField(content, '发色'),
    hairStyle: (() => {
      const hairSection = sliceSection(content, '发型', '面部');
      return fieldValue(hairSection, '发型') || collectField(content, '发型');
    })(),
    hairAccessory: collectField(content, '发饰'),
    eyes: collectField(content, '眼睛'),
    faceShape: collectField(content, '脸型'),
    chest: collectField(content, '胸部'),
    waist: collectField(content, '腰部'),
    legs: collectField(content, '腿部'),
    hips: collectField(content, '臀部'),
    top: collectField(content, '上衣'),
    bottom: collectField(content, '下装'),
    underwear: collectField(content, '内衣'),
    accessory: collectField(content, '配饰'),
    personalityTraits: parseTraitGroups(personalitySection, '核心特质'),
    constitutions: parseTraitGroups(nsfwSection, '核心体质'),
    pussy: collectField(nsfwSection || content, '小穴'),
    anus: collectField(nsfwSection || content, '后庭'),
    fetishes: collectList(nsfwSection || content, '性癖取向').length
      ? collectList(nsfwSection || content, '性癖取向')
      : [''],
    voice: collectField(speechSection || content, '音色'),
    catchphrases: collectList(speechSection || content, '口癖').length
      ? collectList(speechSection || content, '口癖')
      : [''],
    arousedBehaviors: aroused.length ? aroused : [''],
    habits: collectList(habitSection || content, '日常习惯').length
      ? collectList(habitSection || content, '日常习惯')
      : [''],
  };
}

function filled(values: string[]): string[] {
  return values.map(item => item.trim()).filter(Boolean);
}

function kv(indent: string, label: string, value: string): string {
  return `${indent}${label}: ${value.trim()}`;
}

function bullets(indent: string, values: string[]): string[] {
  const items = filled(values);
  return items.map(item => `${indent}- ${item}`);
}

function serializeTraitGroups(kind: string, groups: NamedTraitGroup[]): string[] {
  const lines = [`    ${kind}:`];
  const valid = groups.filter(
    group =>
      group.name.trim() ||
      filled(group.manifestations).length ||
      group.stages.some(stage => stage.name.trim() || filled(stage.items).length),
  );
  if (!valid.length) return lines;
  for (const group of valid) {
    const name = group.name.trim() || '未命名';
    lines.push(`      ${name}:`);
    lines.push('        表现形式:');
    const items = bullets('          ', group.manifestations);
    const stages = group.stages.filter(stage => stage.name.trim() || filled(stage.items).length);
    if (stages.length) {
      lines.push(...items);
      for (const stage of stages) {
        lines.push(`          ${stage.name.trim() || '未命名阶段'}:`);
        const stageItems = bullets('            ', stage.items);
        lines.push(...(stageItems.length ? stageItems : ['            - ']));
      }
    } else {
      lines.push(...(items.length ? items : ['          - ']));
    }
  }
  return lines;
}

