export function parseClassmateProfile(name: string, content: string, custom = false, uid?: number): ClassmateArchive {
  const parsed = parseRoleArchiveName(name);
  return {
    uid,
    name,
    campusType: parsed?.campusType || '',
    content,
    custom,
    displayName: fieldValue(content, '姓名') || parsed?.character || name,
    age: fieldValue(content, '年龄') || '未知',
    gender: fieldValue(content, '性别') || '未知',
    identity: firstIdentity(content) || '未知',
    relation: fieldValue(content, '与{{user}}关系') || fieldValue(content, '与user关系') || '未知',
  };
}

export function buildClassmateEntryName(character: string, campusType: string): string {
  return `${character}_${campusType}_角色档案`;
}

export function buildClassmateTemplate(character: string): string {
  return serializeRoleArchiveForm(emptyRoleArchiveForm(character));
}

export async function loadAllClassmateArchives(): Promise<ClassmateArchive[]> {
  const worldbookName = resolveSakuraWorldbookName();
  if (!worldbookName) return [];
  try {
    const worldbook = await getWorldbook(worldbookName);
    return worldbook
      .map(entry => {
        const parsed = parseRoleArchiveName(entry.name);
        if (!parsed) return null;
        return parseClassmateProfile(entry.name, entry.content, false, entry.uid);
      })
      .filter((item): item is ClassmateArchive => item !== null)
      .sort((a, b) => {
        const typeCmp = a.campusType.localeCompare(b.campusType, 'zh-CN');
        if (typeCmp !== 0) return typeCmp;
        return a.displayName.localeCompare(b.displayName, 'zh-CN');
      });
  } catch (error) {
    console.warn('[校园APP] 无法读取同学角色档案:', error);
    return [];
  }
}

export async function loadClassmateArchives(campusType: string): Promise<ClassmateArchive[]> {
  const all = await loadAllClassmateArchives();
  return all.filter(item => item.campusType === campusType);
}
