import React from 'react';
import { Character } from '../../types';
import { Card } from '../ui/Card';
import { motion } from 'framer-motion';
import { MapPin, Heart } from 'lucide-react';

interface SecretCrushProps {
  crushingCharacters: Character[];
  onCharacterClick: (char: Character) => void;
}

/**
 * 倾心于你模块 (Secret Crush)
 * 用于展示对玩家好感度极高（>=90）的角色列表
 * @param crushingCharacters - 好感度达标的角色数组
 * @param onCharacterClick - 点击角色卡片时触发的回调，用于打开角色详情
 */
export const SecretCrush: React.FC<SecretCrushProps> = ({ crushingCharacters, onCharacterClick }) => {
  return (
    <div className="space-y-3">
      {crushingCharacters.map((char, i) => (
        <Card
          key={char.id}
          whileHover={{ scale: 1.02 }}
          whileTap={{ scale: 0.95 }}
          onClick={() => onCharacterClick(char)}
          initial={{ opacity: 0, scale: 0.95 }}
          animate={{ opacity: 1, scale: 1 }}
          transition={{ delay: 0.3 + i * 0.1 }}
          className="flex items-center justify-between cursor-pointer hover:bg-white/60 transition-colors"
        >
          <div className="flex items-center gap-4">
            {/* 角色头像 */}
            {char.avatar ? (
               <img src={char.avatar} className="w-12 h-12 rounded-full object-cover border-2 border-border-default" alt={char.name}/>
            ) : (
               <div className="w-12 h-12 rounded-full bg-gradient-to-tr from-pink-200 to-rose-300 flex items-center justify-center border-2 border-border-default text-pink-500 font-bold">
                 {char.name[0]}
               </div>
            )}
            <div>
              {/* 角色姓名 */}
              <div className="font-bold text-text-primary">{char.name}</div>
              {/* 角色当前所处位置 */}
              <div className="text-xs text-text-secondary flex items-center gap-1 mt-0.5">
                <MapPin className="w-3 h-3" />
                {char.location}
              </div>
            </div>
          </div>
          {/* 角色对玩家的好感度数值 */}
          <div className="flex items-center gap-1 bg-pink-50/80 px-2 py-0.5 rounded-full border border-pink-100/50">
            <Heart className="w-3 h-3 text-pink-500 fill-pink-500" />
            <span className="text-xs font-bold text-pink-600">{char.affinity}</span>
          </div>
        </Card>
      ))}
      
      {/* 如果没有满足条件的角色，显示提示信息 */}
      {crushingCharacters.length === 0 && (
        <div className="text-center py-6 text-sm text-text-secondary">
          暂无倾心于你的对象，继续努力吧！
        </div>
      )}
    </div>
  );
};
