import { CampusBuildingDef, cloneNormalYouthCampusLayout, sanitizeCampusBuildingMap } from './campusLayout';

export interface CustomCampusType {
  id: string;
  name: string;
}

export interface CustomCampusTrait {
  id: string;
  name: string;
  worldview: string;
  mapLayout: Record<string, CampusBuildingDef>;
}

export const CUSTOM_TYPES_KEY = 'campus-app-custom-campus-types';
export const CUSTOM_TRAITS_KEY = 'campus-app-custom-campus-type-traits';
export const WORLDVIEW_OVERRIDES_KEY = 'campus-app-campus-worldviews';

function readJson<T>(key: string, fallback: T): T {
  try {
    const raw = window.localStorage.getItem(key);
    return raw ? (JSON.parse(raw) as T) : fallback;
  } catch {
    return fallback;
  }
}

function writeJson(key: string, value: unknown) {
  try {
    window.localStorage.setItem(key, JSON.stringify(value));
  } catch {
    // ignore
  }
}

function normalizeTrait(item: Partial<CustomCampusTrait> & { name: string }): CustomCampusTrait {
  return {
    id: item.id || `custom-trait-${item.name}`,
    name: String(item.name).trim(),
    worldview: String(item.worldview || ''),
    mapLayout: sanitizeCampusBuildingMap(item.mapLayout) || cloneNormalYouthCampusLayout(),
  };
}

export function loadCustomCampusTypes(): CustomCampusType[] {
  return readJson<CustomCampusType[]>(CUSTOM_TYPES_KEY, [])
    .filter(item => item && typeof item.id === 'string' && typeof item.name === 'string' && item.name.trim())
    .map(item => ({ id: item.id, name: item.name.trim() }));
}

export function loadCustomCampusTraitsByType(): Record<string, CustomCampusTrait[]> {
  const raw = readJson<Record<string, CustomCampusTrait[]>>(CUSTOM_TRAITS_KEY, {});
  return Object.fromEntries(
    Object.entries(raw).map(([typeId, traits]) => [
      typeId,
      (Array.isArray(traits) ? traits : [])
        .filter(item => item && typeof item.name === 'string' && item.name.trim())
        .map(item => normalizeTrait(item)),
    ]),
  );
}

export function saveCustomCampusCatalog(
  types: CustomCampusType[],
  traits: Record<string, CustomCampusTrait[]>,
) {
  writeJson(CUSTOM_TYPES_KEY, types);
  writeJson(CUSTOM_TRAITS_KEY, traits);
}

export function loadWorldviewOverrides(): Record<string, string> {
  return readJson<Record<string, string>>(WORLDVIEW_OVERRIDES_KEY, {});
}

export function saveWorldviewOverrides(overrides: Record<string, string>) {
  writeJson(WORLDVIEW_OVERRIDES_KEY, overrides);
}

export function deleteCustomCampusType(typeId: string): boolean {
  const types = loadCustomCampusTypes();
  if (!types.some(item => item.id === typeId)) return false;
  const traits = loadCustomCampusTraitsByType();
  delete traits[typeId];
  saveCustomCampusCatalog(types.filter(item => item.id !== typeId), traits);
  return true;
}

export function uniqueCatalogId(existing: Set<string>, preferred: string): string {
  const base = String(preferred || '').trim() || `custom-type-${Date.now().toString(36)}`;
  if (!existing.has(base)) return base;
  let index = 2;
  while (existing.has(`${base}-${index}`)) index += 1;
  return `${base}-${index}`;
}

export function upsertCustomCampusTypes(
  incoming: { id: string; name: string; traits?: CustomCampusTrait[] }[],
): number {
  const types = loadCustomCampusTypes();
  const traits = loadCustomCampusTraitsByType();
  const usedIds = new Set(types.map(item => item.id));
  let written = 0;

  for (const item of incoming) {
    const name = String(item.name || '').trim();
    if (!name) continue;
    const existing = types.find(type => type.id === item.id);
    const id = existing?.id || uniqueCatalogId(usedIds, item.id || name);
    usedIds.add(id);
    const nextTraits = (Array.isArray(item.traits) ? item.traits : [])
      .filter(trait => trait && String(trait.name || '').trim())
      .map(trait => normalizeTrait({
        ...trait,
        name: String(trait.name).trim(),
      }));
    if (existing) {
      existing.name = name;
    } else {
      types.push({ id, name });
    }
    traits[id] = nextTraits;
    written += 1;
  }

  saveCustomCampusCatalog(types, traits);
  return written;
}

export function getCustomCampusTraitLayout(typeId: string, traitId: string): Record<string, CampusBuildingDef> | null {
  const trait = loadCustomCampusTraitsByType()[typeId]?.find(item => item.id === traitId);
  if (!trait) return null;
  return sanitizeCampusBuildingMap(trait.mapLayout) || cloneNormalYouthCampusLayout();
}
