import React, { useRef, useState, PointerEvent, useEffect } from 'react';

export function useDraggableScroll<T extends HTMLElement>() {
  const ref = useRef<T>(null);
  const [isDragging, setIsDragging] = useState(false);
  const [hasDragged, setHasDragged] = useState(false);
  const [startY, setStartY] = useState(0);
  const [startX, setStartX] = useState(0);
  const [scrollTop, setScrollTop] = useState(0);
  const [scrollLeft, setScrollLeft] = useState(0);

  const onPointerDown = (e: PointerEvent<T>) => {
    if (!ref.current) return;
    if ((e.target as HTMLElement | null)?.closest('[data-no-drag-scroll]')) return;
    
    if (e.pointerType === 'mouse' && e.button !== 0) return;
    
    setIsDragging(true);
    setHasDragged(false);
    
    setStartY(e.clientY - ref.current.offsetTop);
    setStartX(e.clientX - ref.current.offsetLeft);
    setScrollTop(ref.current.scrollTop);
    setScrollLeft(ref.current.scrollLeft);
  };

  useEffect(() => {
    const handlePointerUp = () => {
      if (isDragging) {
        setIsDragging(false);
        setTimeout(() => setHasDragged(false), 50);
      }
    };

    const handlePointerMove = (e: globalThis.PointerEvent) => {
      if (!isDragging || !ref.current) return;
      
      const y = e.clientY - ref.current.offsetTop;
      const x = e.clientX - ref.current.offsetLeft;
      const walkY = (y - startY) * 1.5;
      const walkX = (x - startX) * 1.5;
      
      if (Math.abs(walkY) > 5 || Math.abs(walkX) > 5) {
        setHasDragged(true);
      }
      
      ref.current.scrollTop = scrollTop - walkY;
      ref.current.scrollLeft = scrollLeft - walkX;
    };

    if (isDragging) {
      window.addEventListener('pointermove', handlePointerMove);
      window.addEventListener('pointerup', handlePointerUp);
      window.addEventListener('pointercancel', handlePointerUp);
    }

    return () => {
      window.removeEventListener('pointermove', handlePointerMove);
      window.removeEventListener('pointerup', handlePointerUp);
      window.removeEventListener('pointercancel', handlePointerUp);
    };
  }, [isDragging, startY, startX, scrollTop, scrollLeft]);

  const onClickCapture = (e: React.MouseEvent<T> | React.TouchEvent<T>) => {
    if (hasDragged) {
      e.stopPropagation();
      if ('preventDefault' in e && e.cancelable !== false) {
        e.preventDefault();
      }
    }
  };

  return {
    ref,
    onPointerDown,
    onClickCapture,
    style: { cursor: isDragging ? 'grabbing' : 'auto' }
  };
}
