import { GraduationCap, Search, Trash2, UserCircle2, UserRound, Users } from 'lucide-react';
import { useEffect, useMemo, useState } from 'react';
import { CustomCampusTrait, deleteCustomCampusType } from '../../../../游戏开局/campusCatalog';
import { CampusMapPreview } from '../../../../游戏开局/CampusMapPreview';
import {
  campusLayoutToPreviewBuildings,
  cloneNormalYouthCampusLayout,
} from '../../../../游戏开局/campusLayout';
import { deleteCustomIdentity } from '../../../../游戏开局/identities';
import { deleteCustomAppearance, deleteCustomPersonality } from '../../../../游戏开局/traits';
import {
  EnrollmentTab,
  loadEnrollmentCatalog,
} from '../../utils/enrollmentWorkshop';
import { Card } from '../ui/Card';
import { ConfirmDialog } from '../ui/ConfirmDialog';
import { CenterModal } from '../ui/Modal';

const TABS: { id: EnrollmentTab; label: string; icon: typeof GraduationCap }[] = [
  { id: 'campus', label: '校园类型', icon: GraduationCap },
  { id: 'looks', label: '相貌', icon: UserRound },
  { id: 'minds', label: '性格', icon: Users },
  { id: 'identities', label: '身份', icon: UserCircle2 },
];

type DetailState =
  | {
      kind: 'campus';
      title: string;
      extra?: string;
      traits: CustomCampusTrait[];
    }
  | {
      kind: 'text';
      title: string;
      extra?: string;
      content: string;
    };

export function EnrollmentWorkshopPanel({
  tab,
  onTabChange,
  tick = 0,
  onChanged,
}: {
  tab: EnrollmentTab;
  onTabChange: (tab: EnrollmentTab) => void;
  tick?: number;
  onChanged: () => void;
}) {
  const catalog = useMemo(() => loadEnrollmentCatalog(), [tick]);
  const [detail, setDetail] = useState<DetailState | null>(null);
  const [activeTraitId, setActiveTraitId] = useState('');
  const [pending, setPending] = useState<{ tab: EnrollmentTab; id: string; label: string } | null>(null);
  const items = tab === 'campus'
    ? catalog.campusTypes
    : tab === 'looks'
      ? catalog.appearances
      : tab === 'minds'
        ? catalog.personalities
        : catalog.identities;

  useEffect(() => {
    if (!detail || detail.kind !== 'campus') return;
    if (!detail.traits.some(trait => trait.id === activeTraitId)) {
      setActiveTraitId(detail.traits[0]?.id || '');
    }
  }, [detail, activeTraitId]);

  const activeTrait =
    detail?.kind === 'campus'
      ? detail.traits.find(trait => trait.id === activeTraitId) || detail.traits[0] || null
      : null;
  const mapBuildings = useMemo(
    () =>
      campusLayoutToPreviewBuildings(
        activeTrait?.mapLayout || cloneNormalYouthCampusLayout(),
      ),
    [activeTrait],
  );

  const handleDelete = () => {
    if (!pending) return;
    if (pending.tab === 'campus') deleteCustomCampusType(pending.id);
    if (pending.tab === 'looks') deleteCustomAppearance(pending.id);
    if (pending.tab === 'minds') deleteCustomPersonality(pending.id);
    if (pending.tab === 'identities') deleteCustomIdentity(pending.id);
    setPending(null);
    onChanged();
  };

  return (
    <Card className="p-0 overflow-hidden" glass={false}>
      <div className="p-4 border-b border-border-default">
        <h3 className="font-bold text-text-primary">入学档案工坊</h3>
        <p className="text-[11px] text-text-secondary mt-1">管理自定义校园类型与个人信息，不含同学集册、校规和活动</p>
      </div>
      <div className="grid grid-cols-4 gap-1 p-2 bg-gray-50">
        {TABS.map(item => (
          <button
            key={item.id}
            type="button"
            onClick={() => onTabChange(item.id)}
            className={`py-2 rounded-xl text-[11px] font-bold flex flex-col items-center gap-0.5 ${
              tab === item.id ? 'bg-white text-pink-500 shadow-sm' : 'text-text-secondary'
            }`}
          >
            <item.icon className="w-3.5 h-3.5" />
            {item.label}
          </button>
        ))}
      </div>
      <div className="p-3 space-y-2 max-h-[46vh] overflow-y-auto hide-scrollbar">
        {items.map(item => (
          <div key={item.id} className="flex items-center gap-2 rounded-2xl border border-border-default bg-white p-3">
            <div className="min-w-0 flex-1">
              <div className="text-sm font-bold text-text-primary truncate">{item.label}</div>
              <div className="text-[11px] text-text-secondary truncate">{item.extra}</div>
            </div>
            <button
              type="button"
              onClick={() => {
                if (tab === 'campus' && 'traits' in item) {
                  const traits = item.traits || [];
                  setActiveTraitId(traits[0]?.id || '');
                  setDetail({
                    kind: 'campus',
                    title: item.label,
                    extra: item.extra,
                    traits,
                  });
                  return;
                }
                setDetail({
                  kind: 'text',
                  title: item.label,
                  extra: item.extra,
                  content: item.content,
                });
              }}
              className="w-8 h-8 rounded-full bg-gray-50 text-text-secondary flex items-center justify-center shrink-0"
              title="查看详情"
            >
              <Search className="w-4 h-4" />
            </button>
            <button
              type="button"
              onClick={() => setPending({ tab, id: item.id, label: item.label })}
              className="w-8 h-8 rounded-full bg-rose-50 text-rose-500 flex items-center justify-center shrink-0"
              title="删除"
            >
              <Trash2 className="w-4 h-4" />
            </button>
          </div>
        ))}
        {!items.length && <p className="text-xs text-text-secondary text-center py-8">还没有自定义内容</p>}
      </div>
      <CenterModal isOpen={Boolean(detail)} onClose={() => setDetail(null)} className="w-[calc(100%-2rem)] max-w-[320px] max-h-[80vh] p-0">
        {detail?.kind === 'text' && (
          <>
            <div className="p-4 border-b border-border-default">
              <h3 className="font-bold text-text-primary">{detail.title}</h3>
              {detail.extra ? <p className="text-[11px] text-text-secondary mt-1">{detail.extra}</p> : null}
            </div>
            <pre className="p-4 text-xs leading-relaxed text-text-secondary whitespace-pre-wrap break-words overflow-y-auto max-h-[48vh] hide-scrollbar">
              {detail.content || '暂无内容'}
            </pre>
          </>
        )}
        {detail?.kind === 'campus' && (
          <>
            <div className="p-4 border-b border-border-default">
              <h3 className="font-bold text-text-primary">{detail.title}</h3>
              <p className="text-[11px] text-text-secondary mt-1">可切换特性，查看对应世界观与校园地图</p>
            </div>
            <div className="p-3 space-y-3 overflow-y-auto max-h-[60vh] hide-scrollbar">
              {detail.traits.length ? (
                <>
                  <div className="flex flex-wrap gap-2">
                    {detail.traits.map(trait => {
                      const selected = (activeTrait?.id || '') === trait.id;
                      return (
                        <button
                          key={trait.id}
                          type="button"
                          onClick={() => setActiveTraitId(trait.id)}
                          className={`px-3 py-1.5 rounded-xl text-xs font-bold border ${
                            selected
                              ? 'bg-pink-50 text-pink-600 border-pink-300'
                              : 'bg-white text-text-secondary border-border-default'
                          }`}
                        >
                          {trait.name}
                        </button>
                      );
                    })}
                  </div>
                  <div className="rounded-2xl border border-pink-200 bg-pink-50/70 p-3">
                    <p className="text-xs font-bold text-pink-700 mb-1.5">世界观</p>
                    <p className="text-xs leading-5 text-text-secondary whitespace-pre-wrap">
                      {activeTrait?.worldview?.trim() || '这个特性还没有填写世界观内容。'}
                    </p>
                  </div>
                  <div>
                    <p className="text-xs font-bold text-text-secondary mb-1.5">
                      校园地图 · {Object.keys(activeTrait?.mapLayout || {}).length} 个建筑
                    </p>
                    <CampusMapPreview
                      buildings={mapBuildings}
                      heightClass="h-[260px]"
                      hint="可拖动查看该特性对应的校园地图。"
                    />
                  </div>
                </>
              ) : (
                <p className="text-xs text-text-secondary text-center py-8">这个校园类型还没有特性</p>
              )}
            </div>
          </>
        )}
      </CenterModal>
      <ConfirmDialog
        open={Boolean(pending)}
        title="确认删除"
        message={pending ? `确定删除「${pending.label}」？此操作不可撤销。` : ''}
        onClose={() => setPending(null)}
        onConfirm={handleDelete}
      />
    </Card>
  );
}
